import React, { useState, useEffect } from "react";
import { useParams, Link } from "react-router-dom";
import Swal from "sweetalert2";
import "animate.css";
import Cookies from "js-cookie";

import { doc, getDoc } from "firebase/firestore";
import { db } from "../../FireBase/config";

import NotFound from "../NotFound/NotFound";
import Loading from "../Loading/Loading";
import EditTeam from "../../Admin/EditTeams";

import { putData, deleteData } from "../../Hooks/getData";

import "./TeamDetails.css";

const TeamDetails = () => {
  const { id } = useParams();

  const [team, setTeam] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [showModal, setShowModal] = useState(false);
  const [fadeOut, setFadeOut] = useState(false);

  const [editName, setEditName] = useState("");
  const [editCoach, setEditCoach] = useState("");
  const [editCity, setEditCity] = useState("");
  const [editCountry, setEditCountry] = useState("");
  const [editLogo, setEditLogo] = useState("");

  const [isAdmin, setIsAdmin] = useState(false);

  // نقش کاربر از کوکی
  useEffect(() => {
    const userCookie = Cookies.get("user");
    if (userCookie) {
      try {
        const user = JSON.parse(userCookie);
        if (user.role === "admin") setIsAdmin(true);
      } catch (err) {
        console.error("Cookie error:", err);
      }
    }
  }, []);

  // 🔥 گرفتن Team از Firestore
  useEffect(() => {
    const fetchTeam = async () => {
      try {
        const teamRef = doc(db, "Teams", id);
        const teamSnap = await getDoc(teamRef);

        if (!teamSnap.exists()) {
          setError("Team not found!");
          return;
        }

        setTeam({
          id: teamSnap.id,
          ...teamSnap.data(),
        });
      } catch (err) {
        console.error(err);
        setError("Team not found!");
      } finally {
        setLoading(false);
      }
    };

    fetchTeam();
  }, [id]);

  if (loading) return <Loading />;
  if (error) return <NotFound message={error} />;
  if (!team) return <NotFound message="Team not found!" />;

  const openModal = () => {
    setEditName(team.name);
    setEditCoach(team.coach);
    setEditCity(team.city);
    setEditCountry(team.country);
    setEditLogo(team.logo);
    setShowModal(true);
  };

  // ✏️ ویرایش
  const handleSave = async () => {
    const updatedTeam = {
      name: editName,
      coach: editCoach,
      city: editCity,
      country: editCountry,
      logo: editLogo,
    };

    try {
      await putData("Teams", team.id, updatedTeam);
      setTeam({ ...team, ...updatedTeam });
      setShowModal(false);

      Swal.fire({
        title: "ویرایش شد!",
        text: "اطلاعات تیم بروزرسانی شد.",
        icon: "success",
        confirmButtonText: "باشه",
      });
    } catch {
      Swal.fire("خطا!", "ویرایش انجام نشد", "error");
    }
  };

  // 🗑 حذف
  const handleDelete = () => {
    Swal.fire({
      title: "حذف تیم",
      text: "مطمئنی میخوای این تیم رو حذف کنی؟",
      icon: "warning",
      showCancelButton: true,
      confirmButtonText: "بله، حذف کن",
      cancelButtonText: "لغو",
      confirmButtonColor: "#d33",
      cancelButtonColor: "#3085d6",
    }).then(async (res) => {
      if (res.isConfirmed) {
        try {
          setFadeOut(true);

          setTimeout(async () => {
            await deleteData("Teams", team.id);

            Swal.fire("حذف شد!", "تیم با موفقیت حذف شد.", "success");

            setTimeout(() => {
              window.location.href = "/teams";
            }, 600);
          }, 400);
        } catch {
          Swal.fire("خطا!", "مشکلی در حذف رخ داد.", "error");
        }
      }
    });
  };

  return (
    <>
      <div className={`team-details-container ${fadeOut ? "fade-out" : ""}`}>
        <div className="team-details-card">
          <img src={team.logo} alt={team.name} className="details-logo" />

          <div className="details-info">
            <h1 className="details-name">{team.name}</h1>
            <p className="details-coach">مربی: {team.coach}</p>
            <p className="details-location">
              مکان: {team.city}, {team.country}
            </p>

            {isAdmin && (
              <div className="details-actions">
                <button className="edit-btn" onClick={openModal}>
                  ✏️ ویرایش
                </button>
                <button className="delete-btn" onClick={handleDelete}>
                  🗑 حذف
                </button>
              </div>
            )}

            <Link to="/teams" className="back-btn">
              بازگشت
            </Link>
          </div>
        </div>
      </div>

      <EditTeam
        show={showModal}
        onClose={() => setShowModal(false)}
        teamId={team.id} // ← حتماً team.id معتبر باشد
        initialData={team} // ← داده اولیه تیم
      />
    </>
  );
};

export default TeamDetails;
